import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2 } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Setup core container
  const container = new Group();

  // Parse palette
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // Dimensions based on atlas region: 512 x 320 (Aspect ratio: 1.6)
  // Scale to fit the target frame naturally
  const width = 3.2;
  const height = 2.0;

  // 1. STAGE / BACKDROP (Engineered Gradient Surface + Subtle Grain)
  // To avoid a "void" effect, we build a solid background panel for the journal card
  const cardGeometry = new PlaneGeometry(width, height);
  const cardMaterial = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1.0
  });

  // Load the texture (ceramic-grain.map.png)
  const imageUrl = config.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png';
  ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
    tex.colorSpace = 'srgb';
    cardMaterial.map = tex;
    cardMaterial.needsUpdate = true;
  }).catch((err) => {
    console.warn('Failed to load journal card texture:', err);
  });

  // Setup custom UV mapping matching the Atlas Region (0, 0, 512, 320)
  // Source rect: x=0, y=0, w=512, h=320 on an presumed larger atlas, 
  // but if this is the explicit texture, we map the UV range.
  // We'll compute the TSL UV transform node:
  const uvs = uv();
  const scale = vec2(512 / 512, 320 / 320); // Normalized range if single map, or offset if tiled atlas
  const offset = vec2(0.0, 0.0);
  cardMaterial.uvNode = uvs.mul(scale).add(offset);

  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  container.add(cardMesh);

  // 2. ADDITIONAL DEPTH / FRAMING
  // Add an elegant thin border matching the "machined-metal" aesthetic of Nova Atelier
  const borderGeo = new PlaneGeometry(width + 0.04, height + 0.04);
  const borderMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent).multiplyScalar(0.7), // Subtle Red Signal rim
    transparent: true,
    opacity: 0.8
  });
  const borderMesh = new Mesh(borderGeo, borderMat);
  borderMesh.position.z = -0.01;
  container.add(borderMesh);

  // Subtle contrast shadow backing plane to prevent floating void look
  const shadowGeo = new PlaneGeometry(width + 0.3, height + 0.3);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(colors.ink),
    transparent: true,
    opacity: 0.6
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.z = -0.02;
  container.add(shadowMesh);

  // Since it's a sprite render mode with "static composition: no interactivity", 
  // we do not register hover events but ensure a smooth rise-in entry animation
  const tl = gsap.timeline();
  tl.fromTo(container.position,
    { y: -0.6, x: 0 },
    { y: -0.3, x: 0, duration: 0.8, ease: 'power3.out' }
  );

  // Return cleanable Object3D
  container.userData = {
    handlers: {},
    cleanup() {
      if (tl) tl.kill();
      cardGeometry.dispose();
      cardMaterial.dispose();
      borderGeo.dispose();
      borderMat.dispose();
      shadowGeo.dispose();
      shadowMat.dispose();
    }
  };

  return container;
}

export default createNode;
